/* Correctly rounded log, log10 and log2 for a fixed set of inputs, from
   CORE-MATH via gen/gen-log-ref.c -- see gen/README.md.

   Two regions matter and the points are split between them.  Around 1 the
   logarithm cancels: log(1+e) is e to first order, so the argument's leading
   bits carry no information and everything rides on the tail -- a third of the
   points sit within 2^-20 of 1 for that reason.  A third cover [0.5, 2], and a
   third spread over the whole exponent range, which is what tests the reduction
   by the exponent.  The float tables need no such care -- uClibc-ng computes
   logf, log10f and log2f in double and converts, which leaves the error far
   below the float rounding boundary, so every setting hits every point.  */

